const tabId = 118779795;

const listings = await browserjs(tabId, () => {
  // Let's find all listing links / cards
  // Look for links to /listing/
  const links = Array.from(document.querySelectorAll('a[href*="/listing/"]'));
  const uniqueListings = [];
  const seenHrefs = new Set();

  for (const a of links) {
    const href = a.getAttribute('href');
    if (!href || seenHrefs.has(href)) continue;
    seenHrefs.add(href);

    // Find the container card
    let container = a;
    while (container && !container.textContent.includes('$') && container !== document.body) {
      container = container.parentElement;
    }
    // Go up a bit more to get the full card
    let card = container;
    while (card && card.parentElement && card.parentElement !== document.body && card.parentElement.querySelectorAll('a[href*="/listing/"]').length === 1) {
      card = card.parentElement;
    }

    const cardText = (card || a).innerText;

    // Address is usually the text of the link or an h2 / paragraph
    const address = a.textContent?.trim() || '';

    uniqueListings.push({
      href,
      address,
      textSnippet: cardText.replace(/\n+/g, ' | ')
    });
  }

  return {
    count: uniqueListings.length,
    listings: uniqueListings
  };
});

