const details = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/homedetails/"]'));
  const seen = new Set();
  const results = [];

  for (const a of links) {
    const href = a.href;
    if (seen.has(href)) continue;
    seen.add(href);

    // Let's find the enclosing card container
    // Look up parents until we find one that contains the price or has multiple child elements
    let el = a;
    let card = null;
    while (el && el !== document.body) {
      if (el.innerText.includes('$') && (el.innerText.includes('Bed') || el.innerText.includes('bed') || el.innerText.includes('Bath') || el.innerText.includes('bath'))) {
        card = el;
      }
      el = el.parentElement;
    }

    const cardText = card ? card.innerText : a.innerText;

    results.push({
      address: a.innerText.trim(),
      href,
      cardText: cardText.replace(/\n+/g, ' | ')
    });
  }

  return results;
});

