const inspection = await browserjs(tabId, () => {
  const link = document.querySelector('a[href*="/homedetails/"]');
  if (!link) return { error: "No link found" };

  const ancestors = [];
  let curr = link.parentElement;
  while (curr && curr !== document.body) {
    ancestors.push({
      tagName: curr.tagName,
      className: curr.className,
      id: curr.id,
      dataAttributes: Object.keys(curr.dataset),
      childCount: curr.children.length
    });
    curr = curr.parentElement;
  }

  return {
    linkText: link.innerText,
    linkHref: link.href,
    ancestors: ancestors.slice(0, 10)
  };
});

