const tabId = 118779795;

const parsedListings = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('.cx-react-listingCard'));
  return cards.map(c => {
    const link = c.querySelector('a[href*="/homedetails/"]');
    if (!link) return null;
    const address = link.innerText.trim();
    const href = link.href;

    const lines = c.innerText.split('\n').map(t => t.trim()).filter(Boolean);

    // Find price ($...)
    const priceLine = lines.find(l => /^\$[\d,]+$/.test(l)) || '';

    // Find beds, baths, sqft, acres
    let beds = '';
    let baths = '';
    let sqft = '';
    let acres = '';

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].toLowerCase();
      if (line === 'bedrooms' || line === 'beds') {
        beds = lines[i - 1] || '';
      }
      if (line === 'bathrooms' || line === 'baths') {
        baths = lines[i - 1] || '';
      }
      if (line === 'square feet' || line === 'sqft') {
        sqft = lines[i - 1] || '';
      }
      if (line === 'acres' || line === 'acre') {
        acres = lines[i - 1] || '';
      }
    }

    // Additional badges like "New Construction", "Open House", etc.
    const badges = [];
    if (lines.some(l => l.includes('New Construction'))) badges.push('New Construction');
    if (lines.some(l => l.includes('Open:'))) badges.push(lines.find(l => l.includes('Open:')));
    if (lines.some(l => l === 'Compass Coming Soon')) badges.push('Coming Soon');

    return {
      address,
      price: priceLine,
      beds,
      baths,
      sqft,
      acres,
      badges: badges.join(', '),
      url: href
    };
  }).filter(Boolean);
});

console.log(`Successfully parsed ${parsedListings.length} listings from page 1`);
console.log(JSON.stringify(parsedListings.slice(0, 3), null, 2));

