const tabId = 118779795;

const extractCardsFromCurrentPage = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('.cx-react-listingCard'));
  return cards.map(c => {
    const link = c.querySelector('a[href*="/homedetails/"]');
    if (!link) return null;
    const address = link.innerText.trim();
    const href = link.href;

    // Price
    const lines = c.innerText.split('\n').map(t => t.trim()).filter(Boolean);
    const priceLine = lines.find(l => /^\$[\d,]+$/.test(l)) || '';

    // dl items
    const dlItems = Array.from(c.querySelectorAll('dl > div'));
    let beds = '';
    let baths = '';
    let sqft = '';
    let lotSize = '';

    for (const item of dlItems) {
      const text = item.innerText.toLowerCase();
      const val = item.innerText.split('\n')[0].trim();
      if (text.includes('bed')) beds = val;
      else if (text.includes('bath')) baths = val;
      else if (text.includes('square feet') || text.includes('sqft')) sqft = val;
      else if (text.includes('acre') || text.includes('lot')) lotSize = val + ' acres';
    }

    return {
      address,
      price: priceLine,
      beds,
      baths,
      sqft,
      lotSize,
      url: href
    };
  }).filter(Boolean);
});

